fn into_basic(self) -> Self {
    let svm = self
        .with_mainnet_features()
        .with_builtins()
        .with_lamports(1_000_000u64.wrapping_mul(LAMPORTS_PER_SOL))
        .with_sysvars()
        .with_feature_accounts()
        .with_default_programs()
        .with_sigverify(true)
        .with_blockhash_check(true);

    #[cfg(feature = "precompiles")]
    let svm = svm.with_precompiles();

    svm
}

/// Creates the basic test environment.
pub fn new() -> Self {
    LiteSVM::default().into_basic()

/// Returns a [`FeatureSet`] containing only the features currently
/// activated on Solana mainnet-beta.
///
/// The list of active features will need to be refreshed as mainnet
/// activates new features. See also <https://www.simd.wtf/>.
pub fn mainnet_feature_set() -> FeatureSet {
    let mut feature_set = FeatureSet::default();
    for (feature_id, activation_slot) in MAINNET_ACTIVE_FEATURES {
        feature_set.activate(feature_id, *activation_slot);
    }
    feature_set
}

/// Replace the feature set with one matching the features active on
/// Solana mainnet-beta. See [`Self::mainnet_feature_set`].
pub fn with_mainnet_features(self) -> Self {
    self.with_feature_set(Self::mainnet_feature_set())
}

/// Adds an SBF program to the test environment.
///
/// Uses `BPFLoaderUpgradeable` by default for the loader.
pub fn add_program(
    &mut self,
    program_id: impl Into<Address>,
    program_bytes: &[u8],
) -> Result<(), LiteSVMError> {
    self.add_program_internal::<false>(program_id, program_bytes, &bpf_loader_upgradeable::id())
}

/// Adds an SBF program with a specific loader to match mainnet CU behavior.
///
/// Use `bpf_loader::id()` for BPFLoader2, `bpf_loader_deprecated::id()` for BPFLoader1,
/// or `bpf_loader_upgradeable::id()` for the upgradeable loader.
pub fn add_program_with_loader(
    &mut self,
    program_id: impl Into<Address>,
    program_bytes: &[u8],
    loader_id: Address,
) -> Result<(), LiteSVMError> {
    self.add_program_internal::<false>(program_id, program_bytes, &loader_id)
}

/// Adds an SBF program that is known-good and already verified.
